<?php
namespace Joomla\Component\Academy\Administrator\Controller;
defined('_JEXEC') or die;
use Joomla\CMS\Factory;use Joomla\CMS\MVC\Controller\BaseController;use Joomla\CMS\Router\Route;use Joomla\CMS\Session\Session;use Joomla\Database\DatabaseInterface;
final class PollController extends BaseController{public function save():void{Session::checkToken()or jexit('Invalid token');$app=Factory::getApplication();if(!$app->getIdentity()->authorise('core.create','com_academy'))throw new \RuntimeException('Not authorised',403);$in=$app->getInput();$id=$in->post->getInt('id');$row=(object)['id'=>$id?:null,'title'=>trim($in->post->getString('title')),'state'=>$in->post->getInt('state',1),'multiple'=>$in->post->getInt('multiple'),'publish_up'=>$in->post->getString('publish_up')?:null,'publish_down'=>$in->post->getString('publish_down')?:null,'created'=>Factory::getDate()->toSql()];if($row->title==='')throw new \RuntimeException('A poll question is required.',400);$db=Factory::getContainer()->get(DatabaseInterface::class);$id?$db->updateObject('#__academy_polls',$row,'id'):$db->insertObject('#__academy_polls',$row,'id');$db->setQuery($db->createQuery()->delete('#__academy_poll_options')->where('poll_id='.(int)$row->id))->execute();$options=array_values(array_filter(array_map('trim',(array)$in->post->get('options',[],'array'))));if(count($options)<2)throw new \RuntimeException('At least two choices are required.',400);foreach($options as $i=>$title){$o=(object)['poll_id'=>(int)$row->id,'title'=>$title,'ordering'=>$i];$db->insertObject('#__academy_poll_options',$o);}$app->enqueueMessage('Poll saved.');$app->redirect(Route::_('index.php?option=com_academy&view=polls',false));}public function cancel():void{Factory::getApplication()->redirect(Route::_('index.php?option=com_academy&view=polls',false));}}
